#!/usr/bin/env bash
# step38 — Shop-by-Category: truly centered tiles (auto-fit capped grid), no empty column
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step38-$TS
EXPECT_MD5="bf4b7eecf88de251c116fd2b9d3f8dcf"

echo "==> backing up to $BAK"
mkdir -p "$BAK/views"
cp "$APP/views/home.ejs" "$BAK/views/home.ejs"

restore(){ echo "!! restoring home.ejs from backup"; cp "$BAK/views/home.ejs" "$APP/views/home.ejs"; }
trap 'restore' ERR

echo "==> writing new home.ejs"
cat > /tmp/gsz-home-b64.txt <<'B64EOF'

B64EOF
base64 -d /tmp/gsz-home-b64.txt > "$APP/views/home.ejs"
rm -f /tmp/gsz-home-b64.txt

GOT_MD5=$(md5sum "$APP/views/home.ejs" | awk '{print $1}')
echo "   md5 got=$GOT_MD5 expect=$EXPECT_MD5"
if [ "$GOT_MD5" != "$EXPECT_MD5" ]; then echo "!! md5 mismatch"; false; fi

echo "==> ejs compile check"
node -e '
const ejs=require("/opt/gsz/node_modules/ejs");
const fs=require("fs");
const src=fs.readFileSync("/opt/gsz/views/home.ejs","utf8");
ejs.compile(src,{filename:"/opt/gsz/views/home.ejs"});
console.log("   compile OK");
'

echo "==> pm2 restart gsz"
pm2 restart gsz --update-env >/dev/null
sleep 2

echo "==> health check (home page renders)"
HTML=$(curl -s -m 15 http://127.0.0.1:3900/)
echo "$HTML" | grep -q '</html>' || { echo "!! home page did not render"; false; }
echo "$HTML" | grep -q 'Shop by category' || { echo "!! category section missing"; false; }

echo "==> verify centering CSS is live"
echo "$HTML" | grep -q 'auto-fit,minmax(180px,210px)' || { echo "!! centering rule not found in output"; false; }
echo "$HTML" | grep -q 'product<%' && { echo "!! old count markup still present"; false; } || true

trap - ERR
echo "==> step38 OK — Shop-by-Category centered. Backup at $BAK"
